typedef float rational_t;
extern "C" float sqrtf(float);

struct vector4d
{
  rational_t x, y, z, w;
};

class matrix4x4
{
public:
  typedef rational_t T;
  typedef vector4d row;

  row x __attribute__((aligned(16)));
  row y;
  row z;
  row w;

  inline const row & operator[](int i) const
  { return (&x)[i]; }
};

class quaternion
{
public:
  quaternion(const matrix4x4 &M);

  rational_t a;
  rational_t b;
  rational_t c;
  rational_t d;
};

quaternion::quaternion(const matrix4x4 &M)
{
  int        i, j, k;
  rational_t tr, s, q[4];

  tr = M.x.x + M.y.y + M.z.z;
  if(tr > 0.0f)
  {
    s = sqrtf(tr + 1.0f);
    a = s * 0.5f;
    s = 0.5f / s;
    b = (M.z.y - M.y.z) * s;
    c = (M.x.z - M.z.x) * s;
    d = (M.y.x - M.x.y) * s;
  }
  else
  {
    i = 0; j = 1; k = 2;
    if(M.y.y > M.x.x){ i = 1; j = 2; k = 0; }
    if(M.z.z > M[i][i]){ i = 2; j = 0; k = 1; }

    s = sqrtf(M[i][i] - M[j][j] - M[k][k] + 1.0f);
    q[i + 1] = s * 0.5f;
    if(s != 0.0f) s = 0.5f / s;
    q[0] = (M[k][j] - M[j][k]) * s;
    q[j + 1] = (M[j][i] + M[i][j]) * s;
    q[k + 1] = (M[k][i] + M[i][k]) * s;

    a = q[0];
    b = q[1];
    c = q[2];
    d = q[3];
  }
}
